"""Joint S-model P39 x M35 generated by (s_P, s_M): which (productivity, HN) class pairs are realised by actual terms."""
import numpy as np
from verify_model import load
P_reps, P_F, P = load("../data/model39_productivity.txt")
M_reps, M_F, M = load("../data/model35_hn.txt")
sP, sM = P_reps.index("S"), M_reps.index("S")
start = (sP, sM)
seen = {start}; order = [start]; frontier = [start]
while frontier:
    new = []
    for a in list(order):
        for b in list(order):
            for x, y in ((a, b), (b, a)):
                c = (int(P[x[0], y[0]]), int(M[x[1], y[1]]))
                if c not in seen: seen.add(c); order.append(c); new.append(c)
    frontier = new
J = order
idx = {c: i for i, c in enumerate(J)}
n = len(J)
T = np.array([[idx[(int(P[a[0], b[0]]), int(M[a[1], b[1]]))] for b in J] for a in J])
s = idx[start]
viol = sum(1 for x in range(n) for y in range(n) for z in range(n) if T[T[T[s, x], y], z] != T[T[x, z], T[y, z]])
print("joint classes realised:", n, " S-identity violations:", viol)
prodHN = [c for c in J if P_F[c[0]] and not M_F[c[1]]]
print("productive-but-no-hnf joint classes (would refute C6 or Q10):", prodHN)
botP = [c for c in J if not P_F[c[0]]]
print("non-productive joint classes:", len(botP), " of which no-hnf (M35 bottom):", sum(1 for c in botP if not M_F[c[1]]))
print("productive joint classes:", sum(1 for c in J if P_F[c[0]]))
